def convert_to_exponential(x_str):
    # Strip leading and trailing whitespaces
    x_str = x_str.strip()

    # Determine the sign of the exponent
    if '.' in x_str:
        integer_part, fractional_part = x_str.split('.')
        if integer_part.startswith('-'):
            sign = '-'
            integer_part = integer_part[1:]
        elif integer_part.startswith('+'):
            sign = ''
            integer_part = integer_part[1:]
        else:
            sign = ''

        # Count the number of digits before the decimal point
        b = len(integer_part)
        # Strip leading zeroes from fractional part
        fractional_part = fractional_part.lstrip('0')
        if fractional_part:
            a = int(integer_part + fractional_part)
            # Adjust the exponent since fractional part is added to integer part
            b += len(fractional_part) - len(integer_part)
        else:
            a = int(integer_part)
            b = max(0, b - 1)

        # Normalize the number such that 1 <= a < 10
        if a >= 10:
            a_str = str(a)
            a = int(a_str[0])
            b += len(a_str) - 1
    else:
        a = int(x_str)
        b = 0

    # Create the exponential notation
    if b == 0:
        return str(a)
    elif b > 0:
        return f"{a}E{b}"
    else:
        return f"{a}E{b}"

