    # Handle the case where x_str is a simple integer or decimal without exponent
    if 'e' not in x_str and 'E' not in x_str:
        if '.' in x_str:
            # Remove trailing zeros and the decimal point if it's redundant
            x_str = x_str.rstrip('0').rstrip('.')
