        mantissa, exponent = x_str.split('e')
    else:
        mantissa, exponent = x_str.split('E')

    exponent = int(exponent)

    # If mantissa ends with '.', remove it
    if mantissa.endswith('.'):
        mantissa = mantissa[:-1]

    # Remove trailing zeros in mantissa
    mantissa = mantissa.rstrip('0')

    # Remove trailing decimal point if it's left behind
    if mantissa.endswith('.'):
